const params=new URLSearchParams(location.search),state=document.getElementById('state');
const control=document.createElement(params.get('version')==='broken'?'div':'button');control.className='button primary';control.textContent='Continue to PayPal sandbox';if(control.tagName==='DIV')control.setAttribute('role','button');document.getElementById('control').append(control);
async function request(body){const response=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Sandbox request unavailable.');return result;}
control.onclick=async()=>{control.setAttribute('aria-disabled','true');state.textContent='Creating a sandbox order…';try{const data=await request({action:'create'});location.assign(data.approvalUrl);}catch(error){state.textContent=error.message;control.removeAttribute('aria-disabled');}};
if(params.has('cancelled'))state.textContent='Sandbox checkout cancelled. No payment is claimed. You can try again.';
else if(params.has('returned')){state.textContent='Verifying the sandbox capture with PayPal…';try{const receipt=await request({action:'capture',orderId:params.get('token')});document.getElementById('receipt').hidden=false;document.getElementById('receipt-data').textContent=JSON.stringify(receipt,null,2);state.textContent='Completed capture verified by the server.';}catch(error){state.textContent=error.message;}}
else try{const r=await fetch('/api/checkout');const data=await r.json();state.textContent=data.configured?'Sandbox ready. Sign in only with a sandbox buyer account.':'PayPal sandbox setup pending. No payment can be made yet.';}catch{state.textContent='Sandbox API unavailable on this host. Use the configured Vercel deployment.';}
